from cardio_1 import a, G
# I67 — Autres maladies cérébrovasculaires (N-05-Neurologie). Entrées conditionnelles : aucun terme existant dans G n’est écrasé.
# Les noms d’essais, de scores et de gènes dont le dossier de recherche ne donne pas le développement sont écrits honnêtement, sans lettre à lettre inventé.
def add(k, lit, full, d, ref):
    if k not in G:
        a(k, lit, full, '<p>' + d + '</p>', ref)
